const results = await runs.all([
  { key: "local-oauth", agent: "scout", task: "Investigate GitHub issue #942 in repository chrisdoc/hevy-mcp. Work in cwd /root/hevy-mcp-issue-942 at branch investigate/issue-942, based on origin/main. Read the OAuth implementation, its tests, package lock/version history, and relevant deployment/config files. Determine precisely whether CIMD support is implemented, whether the reported Claude request should pass, and identify likely code/deployment mismatch or bug. Do not modify files, commit, push, or comment. Return concise evidence with exact file paths, line ranges, relevant commits, and a confidence-rated diagnosis." },
  { key: "protocol-live", agent: "researcher", task: "Investigate GitHub issue https://github.com/chrisdoc/hevy-mcp/issues/942 as an external/protocol and production-reproduction lane. Check the issue/comments, current public endpoint https://mcp.hevy-mcp.dev, OAuth discovery metadata, CIMD/DCR behavior, and official OAuth/MCP/Claude expectations using safe read-only HTTP requests and primary sources. Compare the observed behavior to the issue's curl. Do not modify any repository files. Return a concise evidence-backed diagnosis, exact request/response observations, likely root cause, and source URLs; distinguish current production behavior from repository HEAD." }
]);
return results.map((result) => ({ key: result.key, output: result.output }));

