interface MemoryKVEntry {
	value: string;
}

function createMemoryKV() {
	const store = new Map<string, MemoryKVEntry>();
	return {
		store,
		get(key: string, options?: { type?: string } | string) {
			const entry = store.get(key);
			if (!entry) return Promise.resolve(null);
			const type = typeof options === "string" ? options : options?.type;
			if (type === "json") {
				try {
					return Promise.resolve(JSON.parse(entry.value));
				} catch (error) {
					return Promise.reject(error);
				}
			}
			return Promise.resolve(entry.value);
		},
		put(key: string, value: string) {
			store.set(key, { value });
			return Promise.resolve();
		},
		delete(key: string) {
			store.delete(key);
			return Promise.resolve();
		},
		list(options?: { prefix?: string }) {
			const prefix = options?.prefix ?? "";
			return Promise.resolve({
				keys: [...store.keys()]
					.filter((name) => name.startsWith(prefix))
					.map((name) => ({ name })),
				list_complete: true,
			});
		},
	};
}

function base64UrlEncode(bytes: Uint8Array): string {
	let binary = "";
	for (const byte of bytes) binary += String.fromCharCode(byte);
	return btoa(binary)
		.replaceAll("+", "-")
		.replaceAll("/", "_")
		.replace(/=+$/, "");
}

const initializeBody = {
	jsonrpc: "2.0",
	id: 1,
	method: "initialize",
	params: {
		protocolVersion: "2025-11-25",
		capabilities: {},
		clientInfo: { name: "oauth-test", version: "1" },
	},
};

async function parseMcpResponse(response: Response): Promise<unknown> {
	const text = await response.text();
	if (response.headers.get("content-type")?.includes("text/event-stream")) {
		const data = text
			.split("\n")
			.find((line) => line.startsWith("data: "))
			?.slice(6);
		if (!data) throw new Error(`Missing SSE data: ${text}`);
		return JSON.parse(data);
	}
	return JSON.parse(text);
}

